static inline HVX_Vector isa_hvx_vec_exp2_f16(HVX_Vector x_v) {
    const HVX_Vector zero_v    = Q6_V_vzero();
    const HVX_Vector half_hf_v = Q6_Vh_vsplat_R(0x3800);  // fp16 0.5

    // Clamp input to prevent integer underflow in FP16-to-INT16 conversion
    const HVX_Vector v_clamp_min = isa_hvx_vec_splat_f16(-24.0f);
    x_v = Q6_Vhf_vmax_VhfVhf(v_clamp_min, x_v);

    // k = round_toward_neg_inf(x);  f = (float)k;  frac = x - f
    HVX_Vector x_minus_half = Q6_Vhf_equals_Vqf16(Q6_Vqf16_vsub_VhfVhf(x_v, half_hf_v));
    HVX_Vector k_v          = Q6_Vh_equals_Vhf(x_minus_half);  // truncate to int16
    HVX_Vector f_v          = Q6_Vhf_equals_Vh(k_v);           // back to fp16

    HVX_Vector x_qf16 = Q6_Vqf16_vsub_VhfVhf(x_v, f_v);        // fractional part in qf16

    // Horner: y = ((((E5*x + E4)*x + E3)*x + E2)*x + E1)*x + E0
    // E5 = ln(2)^6 / 720 as an IEEE half, and the multiply takes it as an IEEE half. Before, the
    // constant was the raw qf16 pattern 0x5082 for the qf16 x qf16 multiply. hexagon-clang 19.0.07
    // emits that multiply as qf16 x hf when it inlines this function into a larger loop. The
    // pattern then reads as 36.06, thus the polynomial gets 36 * x^6 more: 2 % at x = 0.3 and
    // 56 % at x = 0.5. An IEEE constant has the same value in the two forms.
    HVX_Vector y = Q6_Vqf16_vmpy_Vqf16Vhf(x_qf16, Q6_Vh_vsplat_R(0x090c));   // E5*x
    y            = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x157d));        // + E4
    y            = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    y            = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x20ed));        // + E3
    y            = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    y            = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x2b1b));        // + E2
    y            = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    y            = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x33b0));        // + E1
    y            = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    y            = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x398c));        // + E0
    y            = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);                      // y = y * x
    y            = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x3c00));        // + 1.0

    // Combine polynomial (mantissa) with integer part (exponent): result = y * 2^k
    y                          = Q6_Vhf_equals_Vqf16(y);
    HVX_Vector y_exp           = Q6_Vuh_vlsr_VuhR(Q6_Vh_vasl_VhR(y, 1), 11);
    y_exp                      = Q6_Vh_vadd_VhVh(k_v, y_exp);
    HVX_VectorPred q_underflow = Q6_Q_vcmp_gt_VhVh(zero_v, y_exp);
    y                          = Q6_Vh_vaslacc_VhVhR(y, k_v, 10);
    return Q6_V_vmux_QVV(q_underflow, zero_v, y);
}

#define ISA_HVX_EXACT_SPLAT(x) Q6_V_vsplat_R((int32_t) (x))

// The f32 value of an f16 value. The conversion is exact for every f16 value.
static inline HVX_Vector isa_hvx_exact_hf_to_sf(HVX_Vector h) {
    const HVX_Vector zero = Q6_V_vzero();
    const HVX_Vector sign = Q6_Vw_vasl_VwR(Q6_V_vand_VV(h, ISA_HVX_EXACT_SPLAT(0x8000)), 16);
    const HVX_Vector em   = Q6_V_vand_VV(h, ISA_HVX_EXACT_SPLAT(0x7fff));

    // A normal value, Inf or NaN: move the fields up by 13 bits and add the exponent bias
    // difference, 112 for a finite value and 224 for Inf and NaN (exponent 31 goes to 255).
    const HVX_VectorPred q_infnan = Q6_Q_vcmp_gt_VwVw(em, ISA_HVX_EXACT_SPLAT(0x7bff));
    const HVX_Vector     bias     = Q6_V_vmux_QVV(q_infnan, ISA_HVX_EXACT_SPLAT(0x70000000), ISA_HVX_EXACT_SPLAT(0x38000000));
    const HVX_Vector     r_norm   = Q6_Vw_vadd_VwVw(Q6_Vw_vasl_VwR(em, 13), bias);

    // A subnormal value em * 2^-24: the leading one of em is at bit 31 - lz. A shift by lz - 8
    // puts it at bit 23, and the exponent field is 133 - lz, because the leading one adds one.
    const HVX_Vector lz     = Q6_Vuw_vcl0_Vuw(em);
    const HVX_Vector r_sub  = Q6_Vw_vadd_VwVw(Q6_Vw_vasl_VwVw(em, Q6_Vw_vsub_VwVw(lz, ISA_HVX_EXACT_SPLAT(8))),
                                              Q6_Vw_vasl_VwR(Q6_Vw_vsub_VwVw(ISA_HVX_EXACT_SPLAT(133), lz), 23));
    const HVX_VectorPred q_sub = Q6_Q_vcmp_gt_VwVw(ISA_HVX_EXACT_SPLAT(0x0400), em);

    HVX_Vector r = Q6_V_vmux_QVV(q_sub, r_sub, r_norm);
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_eq_VwVw(em, zero), zero, r);
    return Q6_V_vor_VV(r, sign);
}

// The f16 value of an f32 value, with round to nearest even. A value of 65520 or more becomes Inf,
// and a value below 2^-14 becomes an f16 subnormal or zero. The result is in the low halfword.
static inline HVX_Vector isa_hvx_exact_sf_to_hf(HVX_Vector x) {
    const HVX_Vector one  = ISA_HVX_EXACT_SPLAT(1);
    const HVX_Vector sign = Q6_V_vand_VV(Q6_Vuw_vlsr_VuwR(x, 16), ISA_HVX_EXACT_SPLAT(0x8000));
    const HVX_Vector a    = Q6_V_vand_VV(x, ISA_HVX_EXACT_SPLAT(0x7fffffff));

    // A normal result: take off the bias difference 112 << 23, add the half ulp 0xfff and the odd
    // bit for the tie, and shift. A carry moves the value to the next exponent, and an f32 value
    // of 65520 or more gives 0x7c00 or more, thus the minimum with 0x7c00 gives Inf.
    const HVX_Vector odd    = Q6_V_vand_VV(Q6_Vuw_vlsr_VuwR(a, 13), one);
    HVX_Vector       r_norm = Q6_Vw_vadd_VwVw(a, Q6_Vw_vadd_VwVw(odd, ISA_HVX_EXACT_SPLAT(0x0fff - 0x38000000)));
    r_norm = Q6_Vw_vmin_VwVw(Q6_Vuw_vlsr_VuwR(r_norm, 13), ISA_HVX_EXACT_SPLAT(0x7c00));

    // A subnormal result: the value m * 2^(e - 150) becomes m >> (126 - e) units of 2^-24. The
    // dropped bits, moved to the top of the word, are more than half when they are above
    // 0x80000000, and the odd bit of the quotient decides a tie. A shift of 31 gives zero, because
    // m is below 2^24.
    const HVX_Vector     e     = Q6_Vuw_vlsr_VuwR(a, 23);
    const HVX_Vector     m     = Q6_V_vor_VV(Q6_V_vand_VV(a, ISA_HVX_EXACT_SPLAT(0x007fffff)), ISA_HVX_EXACT_SPLAT(0x00800000));
    const HVX_Vector     sh    = Q6_Vw_vmin_VwVw(Q6_Vw_vsub_VwVw(ISA_HVX_EXACT_SPLAT(126), e), ISA_HVX_EXACT_SPLAT(31));
    HVX_Vector           q     = Q6_Vw_vlsr_VwVw(m, sh);
    const HVX_Vector     rest  = Q6_Vw_vasl_VwVw(m, Q6_Vw_vsub_VwVw(ISA_HVX_EXACT_SPLAT(32), sh));
    const HVX_VectorPred q_up  = Q6_Q_vcmp_gt_VuwVuw(Q6_V_vor_VV(rest, Q6_V_vand_VV(q, one)), ISA_HVX_EXACT_SPLAT(0x80000000));
    q = Q6_Vw_condacc_QVwVw(q_up, q, one);

    HVX_Vector r = Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(ISA_HVX_EXACT_SPLAT(0x38800000), a), q, r_norm);
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(a, ISA_HVX_EXACT_SPLAT(0x7f800000)), ISA_HVX_EXACT_SPLAT(0x7e00), r);
    return Q6_V_vor_VV(r, sign);
}

// a * b with round to nearest even. The product of the two 24-bit significands is exact in 48 bits
// (vmpye and vmpyoacc give the 64-bit product), and one rounding makes the f32 result.
static inline HVX_Vector isa_hvx_exact_sf_mul(HVX_Vector a, HVX_Vector b) {
    const HVX_Vector zero = Q6_V_vzero();
    const HVX_Vector one  = ISA_HVX_EXACT_SPLAT(1);
    const HVX_Vector k_ff = ISA_HVX_EXACT_SPLAT(0xff);
    const HVX_Vector k_m  = ISA_HVX_EXACT_SPLAT(0x007fffff);
    const HVX_Vector k_h  = ISA_HVX_EXACT_SPLAT(0x00800000);

    const HVX_Vector sign = Q6_V_vand_VV(Q6_V_vxor_VV(a, b), ISA_HVX_EXACT_SPLAT(0x80000000));
    const HVX_Vector ea   = Q6_V_vand_VV(Q6_Vuw_vlsr_VuwR(a, 23), k_ff);
    const HVX_Vector eb   = Q6_V_vand_VV(Q6_Vuw_vlsr_VuwR(b, 23), k_ff);
    const HVX_Vector ma   = Q6_V_vor_VV(Q6_V_vand_VV(a, k_m), k_h);
    const HVX_Vector mb   = Q6_V_vor_VV(Q6_V_vand_VV(b, k_m), k_h);

    HVX_VectorPair   p  = Q6_W_vmpye_VwVuh(ma, mb);
    p                   = Q6_W_vmpyoacc_WVwVh(p, ma, mb);
    const HVX_Vector hi = Q6_V_hi_W(p);
    const HVX_Vector lo = Q6_V_lo_W(p);

    // t is 1 when the product is in [2^47, 2^48). The significand is then bits 47..24, else bits
    // 46..23. The dropped bits of lo, moved to the top of the word, decide the rounding.
    const HVX_Vector     t    = Q6_Vuw_vlsr_VuwR(hi, 15);
    const HVX_Vector     s9   = Q6_Vw_vsub_VwVw(ISA_HVX_EXACT_SPLAT(9), t);
    HVX_Vector           m    = Q6_V_vor_VV(Q6_Vw_vasl_VwVw(hi, s9), Q6_Vw_vlsr_VwVw(lo, Q6_Vw_vadd_VwVw(t, ISA_HVX_EXACT_SPLAT(23))));
    const HVX_Vector     rest = Q6_Vw_vasl_VwVw(lo, s9);
    const HVX_VectorPred q_up = Q6_Q_vcmp_gt_VuwVuw(Q6_V_vor_VV(rest, Q6_V_vand_VV(m, one)), ISA_HVX_EXACT_SPLAT(0x80000000));
    m = Q6_Vw_condacc_QVwVw(q_up, m, one);

    // e2 + 1 is the biased exponent before a carry of the rounding. m holds the hidden one, which
    // adds 1 to the exponent field, and a carry to 2^24 adds one more.
    const HVX_Vector e2 = Q6_Vw_vadd_VwVw(Q6_Vw_vadd_VwVw(ea, eb), Q6_Vw_vsub_VwVw(t, ISA_HVX_EXACT_SPLAT(128)));
    HVX_Vector       r  = Q6_Vw_vadd_VwVw(Q6_Vw_vasl_VwR(e2, 23), m);
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(zero, e2), zero, r);
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(e2, ISA_HVX_EXACT_SPLAT(253)), ISA_HVX_EXACT_SPLAT(0x7f800000), r);

    // A zero or subnormal input gives zero. Inf gives Inf, and NaN or Inf * 0 gives NaN.
    const HVX_VectorPred q_z   = Q6_Q_or_QQ(Q6_Q_vcmp_eq_VwVw(ea, zero), Q6_Q_vcmp_eq_VwVw(eb, zero));
    const HVX_VectorPred q_s   = Q6_Q_or_QQ(Q6_Q_vcmp_eq_VwVw(ea, k_ff), Q6_Q_vcmp_eq_VwVw(eb, k_ff));
    const HVX_VectorPred q_nan = Q6_Q_or_QQ(q_z, Q6_Q_or_QQ(Q6_Q_vcmp_gt_VuwVuw(Q6_V_vand_VV(a, ISA_HVX_EXACT_SPLAT(0x7fffffff)), ISA_HVX_EXACT_SPLAT(0x7f800000)),
                                                             Q6_Q_vcmp_gt_VuwVuw(Q6_V_vand_VV(b, ISA_HVX_EXACT_SPLAT(0x7fffffff)), ISA_HVX_EXACT_SPLAT(0x7f800000))));
    r = Q6_V_vmux_QVV(q_z, zero, r);
    r = Q6_V_vmux_QVV(q_s, Q6_V_vmux_QVV(q_nan, ISA_HVX_EXACT_SPLAT(0x7fc00000), ISA_HVX_EXACT_SPLAT(0x7f800000)), r);
    return Q6_V_vor_VV(r, Q6_V_vmux_QVV(Q6_Q_and_QQn(q_s, q_nan), sign, Q6_V_vmux_QVV(q_s, zero, sign)));
}

// a + b with round to nearest even. The operand with the larger magnitude is A. The significands
// get 7 guard bits, the shift of B keeps a sticky bit, and one rounding makes the f32 result.
static inline HVX_Vector isa_hvx_exact_sf_add(HVX_Vector a, HVX_Vector b) {
    const HVX_Vector zero = Q6_V_vzero();
    const HVX_Vector one  = ISA_HVX_EXACT_SPLAT(1);
    const HVX_Vector k_ab = ISA_HVX_EXACT_SPLAT(0x7fffffff);
    const HVX_Vector k_m  = ISA_HVX_EXACT_SPLAT(0x007fffff);
    const HVX_Vector k_h  = ISA_HVX_EXACT_SPLAT(0x00800000);

    const HVX_Vector     aa  = Q6_V_vand_VV(a, k_ab);
    const HVX_Vector     ab  = Q6_V_vand_VV(b, k_ab);
    const HVX_VectorPred q_x = Q6_Q_vcmp_gt_VwVw(ab, aa);
    const HVX_Vector     A   = Q6_V_vmux_QVV(q_x, b, a);
    const HVX_Vector     AA  = Q6_V_vmux_QVV(q_x, ab, aa);
    const HVX_Vector     BB  = Q6_V_vmux_QVV(q_x, aa, ab);
    const HVX_Vector     eA  = Q6_Vuw_vlsr_VuwR(AA, 23);
    const HVX_Vector     eB  = Q6_Vuw_vlsr_VuwR(BB, 23);

    // A subnormal B is zero. When A is subnormal, B is too, and the result is zero.
    const HVX_Vector mA = Q6_Vw_vasl_VwR(Q6_V_vor_VV(Q6_V_vand_VV(AA, k_m), k_h), 7);
    HVX_Vector       mB = Q6_Vw_vasl_VwR(Q6_V_vor_VV(Q6_V_vand_VV(BB, k_m), k_h), 7);
    mB = Q6_V_vmux_QVV(Q6_Q_vcmp_eq_VwVw(eB, zero), zero, mB);

    // Align B. A shift of 31 or more leaves zero, because mB is below 2^31. The sticky bit is one
    // when the shift drops a one.
    const HVX_Vector     d    = Q6_Vw_vmin_VwVw(Q6_Vw_vsub_VwVw(eA, eB), ISA_HVX_EXACT_SPLAT(31));
    HVX_Vector           mBs  = Q6_Vw_vlsr_VwVw(mB, d);
    const HVX_VectorPred q_st = Q6_Q_vcmp_eq_VwVw(Q6_Vw_vasl_VwVw(mBs, d), mB);
    mBs = Q6_V_vmux_QVV(q_st, mBs, Q6_V_vor_VV(mBs, one));

    const HVX_VectorPred q_sub = Q6_Q_vcmp_gt_VwVw(zero, Q6_V_vxor_VV(a, b));
    HVX_Vector           M     = Q6_V_vmux_QVV(q_sub, Q6_Vw_vsub_VwVw(mA, mBs), Q6_Vw_vadd_VwVw(mA, mBs));

    // Put the leading one at bit 30. A carry (lz 0) shifts right by one and keeps the sticky bit.
    // The exponent is eA + 1 - lz in both cases.
    const HVX_Vector lz = Q6_Vuw_vcl0_Vuw(M);
    const HVX_Vector Mc = Q6_V_vor_VV(Q6_Vuw_vlsr_VuwR(M, 1), Q6_V_vand_VV(M, one));
    const HVX_Vector Mn = Q6_Vw_vasl_VwVw(M, Q6_Vw_vsub_VwVw(lz, one));
    M                   = Q6_V_vmux_QVV(Q6_Q_vcmp_eq_VwVw(lz, zero), Mc, Mn);
    const HVX_Vector e  = Q6_Vw_vsub_VwVw(Q6_Vw_vadd_VwVw(eA, one), lz);

    // Round to nearest even at bit 7.
    HVX_Vector           m    = Q6_Vuw_vlsr_VuwR(M, 7);
    const HVX_Vector     rest = Q6_Vw_vasl_VwR(M, 25);
    const HVX_VectorPred q_up = Q6_Q_vcmp_gt_VuwVuw(Q6_V_vor_VV(rest, Q6_V_vand_VV(m, one)), ISA_HVX_EXACT_SPLAT(0x80000000));
    m = Q6_Vw_condacc_QVwVw(q_up, m, one);

    HVX_Vector r = Q6_Vw_vadd_VwVw(Q6_Vw_vasl_VwR(Q6_Vw_vsub_VwVw(e, one), 23), m);
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(one, e), zero, r);
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(e, ISA_HVX_EXACT_SPLAT(254)), ISA_HVX_EXACT_SPLAT(0x7f800000), r);
    r = Q6_V_vor_VV(r, Q6_V_vand_VV(A, ISA_HVX_EXACT_SPLAT(0x80000000)));
    // An exact cancellation gives +0. Two zero inputs give -0 only when both are negative.
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_eq_VwVw(M, zero), zero, r);
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_eq_VwVw(eA, zero), Q6_V_vand_VV(Q6_V_vand_VV(a, b), ISA_HVX_EXACT_SPLAT(0x80000000)), r);

    // Inf and NaN: A has the larger magnitude, thus A is Inf or NaN when either is. NaN, and Inf
    // minus Inf, give NaN. Otherwise the result is A.
    const HVX_VectorPred q_s   = Q6_Q_vcmp_gt_VwVw(AA, ISA_HVX_EXACT_SPLAT(0x7f7fffff));
    const HVX_VectorPred q_nan = Q6_Q_or_QQ(Q6_Q_vcmp_gt_VwVw(AA, ISA_HVX_EXACT_SPLAT(0x7f800000)),
                                            Q6_Q_and_QQ(q_sub, Q6_Q_vcmp_eq_VwVw(BB, ISA_HVX_EXACT_SPLAT(0x7f800000))));
    return Q6_V_vmux_QVV(q_s, Q6_V_vmux_QVV(q_nan, ISA_HVX_EXACT_SPLAT(0x7fc00000), A), r);
}



/* The body of hvx_vec_exp2_f16 (hvx-exp.h), stopped after the stage "stage" (1 to 19). Each stage
 * returns the value of one line of the upstream function, thus the census can find the first stage
 * that differs between two versions. Stage 19 is equal to the full function. */
static inline HVX_Vector isa_exp2_f16_stage(HVX_Vector x_v, int stage);

/* The int32 value of an f32 value with round to nearest even, with the rules of the ARM
 * vcvtnq_s32_f32: a value of 2^31 or more saturates, NaN gives 0. Integer instructions only. */
static inline HVX_Vector isa_sf_to_w_rne(HVX_Vector x) {
    const HVX_Vector zero = Q6_V_vzero();
    const HVX_Vector one  = Q6_V_vsplat_R(1);
    const HVX_Vector a    = Q6_V_vand_VV(x, Q6_V_vsplat_R(0x7fffffff));
    const HVX_Vector e    = Q6_Vuw_vlsr_VuwR(a, 23);
    const HVX_Vector m    = Q6_V_vor_VV(Q6_V_vand_VV(a, Q6_V_vsplat_R(0x007fffff)), Q6_V_vsplat_R(0x00800000));
    /* e < 150: a shift right by s = min(150 - e, 31). The dropped bits, moved to the top of the
     * word, are more than half when they are above 0x80000000, and the odd bit decides a tie. */
    const HVX_Vector     s    = Q6_Vw_vmin_VwVw(Q6_Vw_vsub_VwVw(Q6_V_vsplat_R(150), e), Q6_V_vsplat_R(31));
    HVX_Vector           q    = Q6_Vw_vlsr_VwVw(m, s);
    const HVX_Vector     rest = Q6_Vw_vasl_VwVw(m, Q6_Vw_vsub_VwVw(Q6_V_vsplat_R(32), s));
    const HVX_VectorPred up   = Q6_Q_vcmp_gt_VuwVuw(Q6_V_vor_VV(rest, Q6_V_vand_VV(q, one)), Q6_V_vsplat_R(0x80000000));
    q = Q6_Vw_condacc_QVwVw(up, q, one);
    /* e >= 150: a shift left by e - 150, at most 7 below the saturation */
    const HVX_Vector l = Q6_Vw_vasl_VwVw(m, Q6_Vw_vsub_VwVw(e, Q6_V_vsplat_R(150)));
    HVX_Vector       r = Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(Q6_V_vsplat_R(150), e), q, l);
    const HVX_VectorPred neg = Q6_Q_vcmp_gt_VwVw(zero, x);
    r = Q6_V_vmux_QVV(neg, Q6_Vw_vsub_VwVw(zero, r), r);
    r = Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(e, Q6_V_vsplat_R(157)),
                      Q6_V_vmux_QVV(neg, Q6_V_vsplat_R(0x80000000), Q6_V_vsplat_R(0x7fffffff)), r);
    return Q6_V_vmux_QVV(Q6_Q_vcmp_gt_VwVw(a, Q6_V_vsplat_R(0x7f800000)), zero, r);
}

static inline HVX_Vector isa_exp2_f16_stage(HVX_Vector x_v, int stage) {
    const HVX_Vector zero_v    = Q6_V_vzero();
    const HVX_Vector half_hf_v = Q6_Vh_vsplat_R(0x3800);
    const HVX_Vector v_clamp_min = isa_hvx_vec_splat_f16(-24.0f);
    x_v = Q6_Vhf_vmax_VhfVhf(v_clamp_min, x_v);
    if (stage == 1) return x_v;
    HVX_Vector x_minus_half = Q6_Vhf_equals_Vqf16(Q6_Vqf16_vsub_VhfVhf(x_v, half_hf_v));
    if (stage == 2) return x_minus_half;
    HVX_Vector k_v = Q6_Vh_equals_Vhf(x_minus_half);
    if (stage == 3) return k_v;
    HVX_Vector f_v = Q6_Vhf_equals_Vh(k_v);
    if (stage == 4) return f_v;
    HVX_Vector x_qf16 = Q6_Vqf16_vsub_VhfVhf(x_v, f_v);
    if (stage == 5) return x_qf16;
    HVX_Vector y = Q6_Vqf16_vmpy_Vqf16Vhf(x_qf16, Q6_Vh_vsplat_R(0x090c));
    if (stage == 6) return y;
    y = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x157d));
    if (stage == 7) return y;
    y = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    if (stage == 8) return y;
    y = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x20ed));
    if (stage == 9) return y;
    y = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    if (stage == 10) return y;
    y = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x2b1b));
    if (stage == 11) return y;
    y = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    if (stage == 12) return y;
    y = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x33b0));
    if (stage == 13) return y;
    y = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    if (stage == 14) return y;
    y = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x398c));
    if (stage == 15) return y;
    y = Q6_Vqf16_vmpy_Vqf16Vqf16(y, x_qf16);
    if (stage == 16) return y;
    y = Q6_Vqf16_vadd_Vqf16Vhf(y, Q6_Vh_vsplat_R(0x3c00));
    if (stage == 17) return y;
    y = Q6_Vhf_equals_Vqf16(y);
    if (stage == 18) return y;
    HVX_Vector y_exp = Q6_Vuh_vlsr_VuhR(Q6_Vh_vasl_VhR(y, 1), 11);
    y_exp = Q6_Vh_vadd_VhVh(k_v, y_exp);
    HVX_VectorPred q_underflow = Q6_Q_vcmp_gt_VhVh(zero_v, y_exp);
    y = Q6_Vh_vaslacc_VhVhR(y, k_v, 10);
    return Q6_V_vmux_QVV(q_underflow, zero_v, y);
}

